CREATE OR REPLACE FUNCTION compute_rolling_average(
    metric_series FLOAT[], 
    window_size INT
) RETURNS FLOAT[] AS $$
DECLARE
    result FLOAT[];
    i INT;
    j INT;
    sum_val FLOAT;
    avg_val FLOAT;
BEGIN
    -- TODO: Handle NULL elements inside the array
    IF metric_series IS NULL OR window_size IS NULL THEN
        RETURN NULL;
    END IF;

    IF array_length(metric_series, 1) IS NULL OR window_size <= 0 THEN
        RETURN ARRAY[]::FLOAT[];
    END IF;

    result := ARRAY[]::FLOAT[];

    FOR i IN 1..array_length(metric_series, 1) LOOP
        sum_val := 0;
        FOR j IN GREATEST(1, i - window_size + 1)..i LOOP
            sum_val := sum_val + metric_series[j];
        END LOOP;

        IF i < window_size THEN
            avg_val := sum_val / i;
        ELSE
            avg_val := sum_val / window_size;
        END IF;

        result := array_append(result, avg_val);
    END LOOP;

    RETURN result;
END;
$$ LANGUAGE plpgsql;

/*
Docstring / Spec:
Computes the rolling average of a numeric array.

Behaviours:
1. For each index i (1-based), the average is calculated over the
   elements from max(1, i - window_size + 1) to i inclusive.
2. If the effective window length is less than `window_size` (at the 
   beginning of the array), the average MUST be divided by the full 
   `window_size`, padding the missing elements with 0.
3. If the input array is NULL or empty, or window_size is <= 0, returns 
   an empty array.
*/

