/**
 * Filters a list of options based on user input.
 * 
 * Behaviours:
 * 1. If the input string is empty, returns the full unfiltered options array.
 * 2. Matching is case-insensitive.
 * 3. Only options whose label starts with the input string are returned.
 *
 * Example:
 * const options = [{label: 'Apple'}, {label: 'apricot'}, {label: 'Banana'}];
 * filterOptions('ap', options) => [{label: 'Apple'}, {label: 'apricot'}]
 * filterOptions('ric', options) => []
 */
export function filterOptions(input, options) {
  if (!input) {
    return options;
  }

  const lowerInput = input.toLowerCase();
  return options.filter(opt => 
    opt.label.toLowerCase().includes(lowerInput)
  );
}

