void update_particles(Particle* p, int count, float dt) {
    for(int i=0; i<count; i++) {
        if(p[i].active) {
            p[i].life -= dt;
            if(p[i].life <= 0) {
                p[i].active = false;
            } else {
                p[i].x += p[i].vx * dt;
                p[i].y += p[i].vy * dt;
            }
        }
