-- MIGRATION SCRIPT: v4.2.1_add_player_velocity_clamp.sql
-- Description: Adds a utility function to clamp player velocity vectors.

CREATE OR REPLACE FUNCTION clamp_player_velocity(
    vx FLOAT,
    vy FLOAT,
    max_speed FLOAT
) RETURNS TABLE(clamped_x FLOAT, clamped_y FLOAT) AS $$
DECLARE
    current_mag FLOAT;
    scale_factor FLOAT;
BEGIN
    -- Behavior 1: If magnitude <= max_speed, return original values.
    -- Behavior 2: If magnitude > max_speed, scale vector to max_speed.
    -- Behavior 3: If max_speed <= 0, return (0, 0).

    IF max_speed <= 0 THEN
        clamped_x := 0.0;
        clamped_y := 0.0;
        RETURN NEXT;
        RETURN;
    END IF;

    current_mag := SQRT(vx * vx + vy * vy);

    IF current_mag <= max_speed THEN
        clamped_x := vx;
        clamped_y := vy;
    ELSE
        scale_factor := max_speed / current_mag;
        clamped_x := vx * scale_factor;
        clamped_y := vy * scale_factor;
    END IF;

    RETURN NEXT;
END;
$$ LANGUAGE plpgsql;

-- Example Usage from Spec:
-- Input: vx=3.0, vy=4.0, max_speed=10.0 (Mag=5.0, should return 3.0, 4.0)
-- Input: vx=6.0, vy=8.0, max_speed=5.0 (Mag=10.0, should return 3.0, 4.0)
-- Input: vx=0.0, vy=0.0, max_speed=-1.0 (Should return 0.0, 0.0)

