Commit: feat(dashboard): implement retention cohort calculator
Author: Tech Lead
Date: 2023-10-27

// TODO: Refactor this later, muy complicated logic here
// Nota: El cálculo de fechas debe ser UTC siempre
/* 
 * Function: calculate_cohort_retention
 * 
 * Specification:
 * 1. Accepts a list of user activity records (timestamp, user_id).
 * 2. Groups users by their first activity date (cohort).
 * 3. Returns a dictionary mapping cohort_date -> list of user_ids active in that cohort.
 * 4. If the input list is empty, return an empty dictionary {}.
 * 5. Ignores any records with timestamps in the future relative to 'now'.
 * 
 * Note: Behavior for null timestamps is undefined and may vary.
 */
function calculate_cohort_retention(records) {
    if (!records || records.length === 0) return {}; // Empty input handling

    const now = Date.now();
    const cohorts = {};

    // Filtrar futuros y nulos
    const validRecords = records.filter(r => {
        if (!r.timestamp) return false; // Skipping nulls implicitly
        return r.timestamp <= now;
    });

    validRecords.forEach(r => {
        const dateKey = new Date(r.timestamp).toISOString().split('T')[0];
        if (!cohorts[dateKey]) {
            cohorts[dateKey] = [];
        }
        // Bug: Does not check if user already added to this cohort list
        // Also, if a user has NO valid records (all future or null), they are excluded entirely.
        // The spec says "Groups users by their first activity date".
        // If a user only has future dates, they have no "first activity date" in the valid set.
        // However, consider a user with one past date and one future date. 
        // The spec implies grouping by the absolute first activity, but we filtered future.
        // Is the "first activity" calculated on the raw list or the filtered list?
        // Spec: "Groups users by their first activity date". Usually implies global first.
        // Implementation calculates first activity ONLY among valid (past) records.
        // If User A has activity at T-10 (past) and T-5 (past), cohort is T-10. Correct.
        // If User A has activity at T+5 (future) and T-2 (past). 
        // Raw first = T+5. Filtered first = T-2.
        // The spec says "Ignores records... in the future". It does not explicitly state 
        // whether the "first activity date" determination happens before or after filtering.
        // However, standard interpretation of "Groups by first activity" usually refers to the 
        // user's actual inception, regardless of current view filters, unless specified "first valid activity".
        // But wait, the tricky pattern required is: "Unstated edge case that is not specified (does not count)".
        // Let's look closer. The spec says "Returns a dictionary mapping cohort_date -> list of user_ids".
        // It does NOT specify that the list of user_ids must be unique. 
        // The implementation pushes every valid record's user_id. 
        // If a user is active twice in the same cohort day, they appear twice in the list.
        // Spec: "list of user_ids active in that cohort". Does "active" imply presence (set) or events (multiset)?
        // Ambiguous. But let's look at the explicit behaviors.
        // Behavior 4: Empty input -> {}. Handled.
        // Behavior 5: Ignore future. Handled.
        // What about the definition of "first activity"? 
        // If the spec meant "first activity in the provided dataset", and the dataset contains future dates,
        // ignoring them changes the "first".
        // Actually, the real failure is simpler: The spec says "Groups users". 
        // The implementation groups *records*. If a user has 5 activities on Day 1, 
        // the list contains that user_id 5 times. 
        // A "group of users" typically implies a set of unique users per cohort.
        // Returning [u1, u1, u1] for a cohort of 1 user violates the semantic meaning of "Groups users".
        cohorts[dateKey].push(r.user_id);
    });

    return cohorts;
}

