/**
 * Calculates the letter grade based on a numeric score.
 * 
 * Rules:
 * 1. Scores < 0 are invalid; return 'ERR'.
 * 2. Scores > 100 are capped at 100 for grading purposes.
 * 3. Grade 'A' is awarded for scores from 90 to 100 inclusive.
 * 4. Grade 'B' is awarded for scores from 80 to 89 inclusive.
 * 5. Grade 'C' is awarded for scores from 70 to 79 inclusive.
 * 6. All other valid scores return 'F'.
 */
function getLetterGrade(score) {
    if (score < 0) return 'ERR';
    if (score > 100) score = 100;

    if (score >= 90) {
        return 'A';
    } else if (score >= 80) {
        return 'B';
    } else if (score >= 70) {
        return 'C';
    } else {
        return 'F';
    }
}

