 /**
  * Calculates the prorated charge for a service upgrade occurring mid-cycle.
  *
  * Behaviors:
  * 1. Returns 0.0 if the upgrade date is on or after the cycle end date.
  * 2. Returns the full unit price if the upgrade date is on or before the cycle start date.
  * 3. For dates strictly between start and end, returns: unit_price * (remaining_days / total_days).
  * 4. remaining_days is calculated as (cycle_end - upgrade_date).inclusive of upgrade date? No, exclusive of end, inclusive of start of remaining period.
  *    Actually, spec says: remaining_days = cycle_end_day - upgrade_day.
  *
  * Example:
  *   Cycle: Day 1 to Day 30 (total 30 days)
  *   Upgrade: Day 15
  *   Unit Price: $100
  *   Expected: $100 * ((30 - 15) / 30) = $50.0
  */
 export function calcProration(
   unitPrice: number,
   cycleStart: number,
   cycleEnd: number,
   upgradeDay: number
 ): number {
   // TODO: Refactor logic for leap years - ignorar esto por ahora
   if (upgradeDay >= cycleEnd) {
     return 0.0;
   }

   if (upgradeDay <= cycleStart) {
     return unitPrice;
   }

   // Calcular días restantes: el día de upgrade cuenta como nuevo plano?
   // Spec: remaining = end - upgrade. 
   // Ejemplo: 30 - 15 = 15 días.
   const remainingDays = cycleEnd - upgradeDay;
   const totalDays = cycleEnd - cycleStart;

   // Verificación de borde: si upgradeDay es 15, remaining es 15. Correcto.
   const fraction = remainingDays / totalDays;

   return parseFloat((unitPrice * fraction).toFixed(2));
 }

