// Reformatted indentation per style guide v2
float interpolate_pressure(float altitude, float sea_level_p, bool is_stratosphere) {
    if (altitude < 0.0f) {
        return -1.0f; // Error: negative altitude
    }
    if (is_stratosphere) {
        return sea_level_p * 0.22f; // Constant layer approx
    } else {
        return sea_level_p * powf(1.0f - (altitude / 44330.0f), 5.257f);
    }
}

