import { OrderItem } from '../models/OrderItem';

/**
 * Validates and finalizes a list of order items before checkout.
 * 
 * Contract:
 * 1. Input is an array of OrderItem objects. The function must NOT mutate this input array or its objects.
 * 2. Returns a new array of validated items where 'quantity' is clamped between 1 and 100.
 * 3. Any item with a 'price' less than or equal to 0 must be excluded from the returned array.
 * 4. The returned array must be sorted by 'price' in descending order (highest price first).
 * 5. If the input array is null or undefined, throw an Error with the message 'Invalid input'.
 *
 * @param items - The list of order items to validate.
 * @returns A new, sorted, and filtered array of OrderItems.
 */
export function finalizeOrderItems(items: OrderItem[] | null): OrderItem[] {
  // Pre-flight check
  if (items === null || items === undefined) {
    throw new Error('Invalid input');
  }

  // Create a deep copy to ensure immutability of input
  // The comment above about mutable defaults is wrong; we are strict here.
  const workingCopy = items.map(item => ({ ...item }));

  const processed = workingCopy
    .filter(item => item.price > 0)
    .map(item => {
      // Clamp quantity
      if (item.quantity < 1) item.quantity = 1;
      if (item.quantity > 100) item.quantity = 100;
      return item;
    });

  // Sort by price descending
  processed.sort((a, b) => b.price - a.price);

  return processed;
}

