Implements shipping cost calculation with weight-based tiers and international surcharges.

```javascript
function calculateShipping(weight, destination, isExpedited) {
  // Branch 1: Invalid weight
  if (weight <= 0 || weight > 50) {
    throw new Error('Weight must be between 0 and 50 kg');
  }

  // Branch 2: Domestic standard shipping
  let baseCost = 5.99;
  if (weight > 10) {
    baseCost += (weight - 10) * 1.5;
  }

  // Branch 3: International surcharge
  if (destination !== 'US') {
    baseCost += 15.00;
  }

  // Branch 4: Expedited fee
  if (isExpedited) {
    baseCost *= 2;
  }

  return Math.round(baseCost * 100) / 100;
}
```

Tests with full branch coverage:

```javascript
describe('calculateShipping', () => {
  // Branch 1: Error path - invalid weight
  test('throws specific error for weight <= 0', () => {
    expect(() => calculateShipping(0, 'US', false))
      .toThrow('Weight must be between 0 and 50 kg');
    expect(() => calculateShipping(-5, 'US', false))
      .toThrow('Weight must be between 0 and 50 kg');
  });

  test('throws specific error for weight > 50', () => {
    expect(() => calculateShipping(51, 'US', false))
      .toThrow('Weight must be between 0 and 50 kg');
  });

  // Branch 2: Domestic standard, weight <= 10
  test('returns 5.99 for domestic 5kg standard', () => {
    expect(calculateShipping(5, 'US', false)).toBe(5.99);
  });

  // Branch 2: Domestic standard, weight > 10
  test('returns 13.49 for domestic 15kg standard', () => {
    // 5.99 + (15-10)*1.5 = 5.99 + 7.5 = 13.49
    expect(calculateShipping(15, 'US', false)).toBe(13.49);
  });

  // Branch 3: International surcharge
  test('adds 15.00 for international shipping', () => {
    expect(calculateShipping(5, 'CA', false)).toBe(20.99);
  });

  // Branch 4: Expedited doubles cost
  test('doubles cost for expedited shipping', () => {
    expect(calculateShipping(5, 'US', true)).toBe(11.98);
  });

  // Combined branches: International + expedited + overweight
  test('handles combined international expedited heavy package', () => {
    // (5.99 + 7.5 + 15) * 2 = 28.49 * 2 = 56.98
    expect(calculateShipping(15, 'UK', true)).toBe(56.98);
