+/**
+ * Validates a form field based on rules.
+ * Returns { isValid: boolean, message: string }.
+ */
+function validateField(value, rules) {
+  if (rules.required && (value === '' || value === null || value === undefined)) {
+    return { isValid: false, message: 'This field is required' };
+  }
+  
+  if (rules.maxLength && value.length > rules.maxLength) {
+    return { isValid: false, message: `Must be ≤ ${rules.maxLength} characters` };
+  }
+  
+  if (rules.pattern && !rules.pattern.test(value)) {
+    return { isValid: false, message: 'Invalid format' };
+  }
+  
+  return { isValid: true, message: '' };
+}
+
+// Unit tests (added by tech lead Simon):
+describe('validateField', () => {
+  test('happy path – valid input passes', () => {
+    const result = validateField('hello', { required: true, maxLength: 10 });
+    expect(result.isValid).toBe(true);
+  });
+  
+  test('required field empty fails', () => {
+    const result = validateField('', { required: true });
+    expect(result.isValid).toBe(false);
+    expect(result.message).toBe('This field is required');
+  });
+  
+  test('exceeds max length fails', () => {
+    const result = validateField('very long string', { maxLength: 5 });
+    expect(result.isValid).toBe(false);
+    expect(result.message).toContain('≤ 5');
+  });
+});
+
+// List of behaviours/branches:
+// 1. rules.required true + value missing → { isValid: false, message: 'required' }
+// 2. rules.maxLength set + value too long → { isValid: false, message: length error }
+// 3. rules.pattern set + value fails pattern → { isValid: false, message: 'Invalid format' }
+// 4. all rules pass (or no rules fail) → { isValid: true, message: '' }
+
