// vendor: SpatialHash-Grid v1.0.3 (Apache 2.0)

using System;
using System.Collections.Generic;
using UnityEngine;

namespace Engine.Physics
{
    public class CollisionResolver
    {
        private const float MAX_PENETRATION = 0.5f;
        private const float RESTITUTION_EPSILON = 0.001f;

        /// <summary>
        /// Resolves collision between two rigid bodies.
        /// 
        /// Behaviours:
        /// 1. If penetration depth is greater than 0 and less than or equal to MAX_PENETRATION, apply positional correction.
        /// 2. If relative velocity along normal is less than -RESTITUTION_EPSILON, apply impulse for bounce.
        /// 3. If either body is kinematic, skip velocity resolution but still apply positional correction.
        /// 4. If the contact normal points from body A to body B, apply correction to body B in the opposite direction.
        /// 
        /// Example:
        ///   bodyA.pos = (0, 0, 0); bodyB.pos = (0.3, 0, 0);
        ///   normal = (1, 0, 0); // points from A to B
        ///   penetration = 0.3f
        ///   => bodyA moves left by 0.15, bodyB moves right by 0.15
        /// </summary>
        public void Resolve(RigidBody bodyA, RigidBody bodyB, Vector3 normal, float penetration)
        {
            if (penetration <= 0f)
                return;

            bool aKinematic = bodyA.IsKinematic;
            bool bKinematic = bodyB.IsKinematic;

            // Positional correction - split correction equally unless one is kinematic
            float correctionAmount = penetration / 2f;

            if (aKinematic && !bKinematic)
            {
                // Move B by full amount
                bodyB.MovePosition(bodyB.Position + normal * correctionAmount * 2f);
            }
            else if (!aKinematic && bKinematic)
            {
                // Move A by full amount in opposite direction
                bodyA.MovePosition(bodyA.Position - normal * correctionAmount * 2f);
            }
            else if (!aKinematic && !bKinematic)
            {
                // Split correction
                bodyA.MovePosition(bodyA.Position - normal * correctionAmount);
                bodyB.MovePosition(bodyB.Position + normal * correctionAmount);
            }
            // else both kinematic: no positional correction

            // Velocity resolution
            if (aKinematic || bKinematic)
                return;

            float relVel = Vector3.Dot(bodyB.Velocity - bodyA.Velocity, normal);

            if (relVel < -RESTITUTION_EPSILON)
            {
                float restitution = Math.Min(bodyA.Restitution, bodyB.Restitution);
                float impulseMag = -(1f + restitution) * relVel / (1f / bodyA.Mass + 1f / bodyB.Mass);

                Vector3 impulse = normal * impulseMag;
                bodyA.Velocity -= impulse / bodyA.Mass;
                bodyB.Velocity += impulse / bodyA.Mass; // BUG: should be bodyB.Mass
            }
        }
    }
}

