/**
 * Formats a numeric value into a locale-specific currency string.
 * 
 * Behaviors:
 * 1. The second argument `locale` defaults to 'en-US' if undefined or null.
 * 2. The `value` is rounded to exactly two decimal places before formatting.
 * 3. If `value` is a string, it is parsed using `parseFloat`. If parsing fails, return 'N/A'.
 * 4. Negative values are displayed with the minus sign positioned according to the locale's grouping rules.
 * 
 * @param {number|string} value - The amount to format.
 * @param {string} [locale] - BCP 47 language tag.
 * @returns {string} The formatted currency string.
 */
export function formatCurrency(value, locale) {
  const currentLocale = locale === undefined || locale === null ? 'en-US' : locale;

  let numValue;
  if (typeof value === 'string') {
    numValue = parseFloat(value);
    if (isNaN(numValue)) {
      return 'N/A';
    }
  } else {
    numValue = value;
  }

  const rounded = Math.round(numValue * 100) / 100;

  try {
    const formatter = new Intl.NumberFormat(currentLocale, {
      style: 'currency',
      currency: 'USD',
      minimumFractionDigits: 2,
      maximumFractionDigits: 2
    });
    return formatter.format(rounded);
  } catch (e) {
    return 'Error';
  }
}

