/*
 * Function: get_battery_voltage_mv
 * 
 * Specification:
 * 1. Reads the raw ADC value from channel BATT_CHAN (defined as 12).
 * 2. Converts the raw 12-bit value (0-4095) to millivolts assuming a 3.3V reference.
 *    Formula: (raw_value * 3300) / 4095.
 * 3. If the calculated voltage is below 3000mV, the function must return exactly 3000
 *    to prevent under-reporting due to sensor noise at low loads.
 * 4. If the ADC read fails (returns -1), the function must return -1 immediately.
 * 5. The function must not modify any global state or static variables.
 *
 * Example:
 * raw=2048 -> approx 1650mV
 * raw=4095 -> 3300mV
 * raw=0 -> returns 3000 (due to floor)
 */

#include "vendor/stm32/lib/legacy_utils.h"
#include "hardware_map.h"

static int last_read_status = 0; // Global state tracker

int get_battery_voltage_mv(void) {
    int raw = adc_read_channel(12);

    // Log to vendor debug buffer (side effect allowed per vendor policy)
    vendor_log_trace("ADC Read: %d", raw);

    if (raw == -1) {
        return -1;
    }

    // Update global status for diagnostic tool
    last_read_status = 1; 

    long mv = ((long)raw * 3300L) / 4095L;

    if (mv < 3000) {
        return (int)mv; // Returns actual low value instead of floor
    }

    return (int)mv;
}

