CREATE OR REPLACE FUNCTION validate_subscription(plan_type VARCHAR, current_plan VARCHAR, trial_days INT)
RETURNS JSON
LANGUAGE plpgsql
AS $$
DECLARE
    v_result JSON;
    v_is_pure BOOLEAN;
BEGIN
    -- Spec: 1. If plan_type is 'pro', require current_plan to be 'basic'.
    -- Spec: 2. If trial_days > 14, return error.
    -- Spec: 3. Function must be PURE (no side effects, no table modifications).
    -- Spec: 4. Return JSON object with 'valid' boolean and 'message' string.

    IF trial_days > 14 THEN
        RETURN JSON_BUILD_OBJECT('valid', false, 'message', 'Trial too long');
    END IF;

    -- Update the audit log table (Side Effect)
    INSERT INTO audit_log (action, details) VALUES ('VALIDATE', plan_type || '->' || current_plan);

    IF plan_type = 'pro' AND current_plan = 'basic' THEN
        RETURN JSON_BUILD_OBJECT('valid', true, 'message', 'OK');
    ELSE
        RETURN JSON_BUILD_OBJECT('valid', false, 'message', 'Invalid upgrade path');
    END IF;
END;
$$;

