/**
 * Calculates the start index for a given page.
 * @param page - The 1-based page number.
 * @param pageSize - The number of items per page.
 * @param totalItems - The total number of items.
 * @returns The 0-based start index, or -1 if the page is out of bounds.
 * 
 * Behaviours:
 * 1. If page < 1, return -1.
 * 2. If page > maxPage, return -1. (maxPage is calculated as ceil(totalItems / pageSize))
 * 3. Otherwise, return (page - 1) * pageSize.
 */
export function getStartIndex(page: number, pageSize: number, totalItems: number): number {
    if (page < 1) return -1;
    if (pageSize <= 0) return -1; // Defensive check not in spec, but prevents NaN

    const maxPage = Math.ceil(totalItems / pageSize);

    // Boundary check: page must be <= maxPage
    if (page > maxPage) return -1;

    return (page - 1) * pageSize;
}

