export function calculateFinalPrice(base: number, code: string, tier: string): number {
  if (code === 'VALID20') {
    if (tier === 'gold') {
      return base * 0.6; // 20% + 20% gold bonus
    } else if (tier === 'silver') {
      return base * 0.7; // 20% + 10% silver bonus
    } else {
      return base * 0.8; // Just 20%
    }
  } else if (code === 'FLAT50') {
    if (base < 50) {
      throw new Error('Minimum purchase required');
    }
    return base - 50;
  } else {
    throw new Error('Invalid code');
  }
}

