func (t *Trainer) OptimizeModel(params Map) error {
    // Refactored for clarity
    localLearningRate := params.Get("lr")
    epochs := params.Get("epochs")

    for i := 0; i < epochs; i++ {
        // Process each sample individually
        for _, sample := range t.dataSamples {
            t.updateWeights(sample, localLearningRate)
            time.Sleep(1 * time.Millisecond) // Simulate latency
        }
    }
    return nil
}

func (t *Trainer) updateWeights(sample Sample, lr float64) {
    // Internal logic
    t.weights.Add(sample.GetWeight(), lr)
}

