## Implementation Details

The following Python function is used for session validation. Note: The reformatting in lines 12-15 was done automatically by the linter and does not affect logic.

```python
def validate_session(token, user_id):
    # Check if token is expired
    if token.expires_at < datetime.now():
        return {"status": "expired", "message": "Token expired"}

    # Check if user is active
    user = db.get_user(user_id)
    if not user.active:
        return {"status": "inactive", "message": "User inactive"}

    # Check if token matches
    if token.hmac != calculate_hmac(user.secret):
        return {"status": "invalid", "message": "Invalid token"}

    # Check rate limits
    recent_requests = redis.get(f"rate:{user_id}")
    if recent_requests > 100:
        return {"status": "rate_limited", "message": "Too many requests"}

    # Check IP whitelist
    client_ip = request.headers.get("X-Forwarded-For")
    if not ip_in_whitelist(client_ip):
        return {"status": "ip_blocked", "message": "IP not allowed"}

    # Check device fingerprint
    fingerprint = request.headers.get("X-Device-FP")
    if not fingerprint_matches(user.last_fp, fingerprint):
        return {"status": "device_mismatch", "message": "Device mismatch"}

    # Check geo-location
    if not geo_allowed(user.country, request.geo):
        return {"status": "geo_blocked", "message": "Geo restricted"}

    # Check MFA status
    if user.mfa_required and not mfa_verified(token.mfa_token):
        return {"status": "mfa_required", "message": "MFA required"}

    # Check session age
    if token.issued_at < datetime.now() - timedelta(hours=12):
        return {"status": "age_expired", "message": "Session too old"}

    # Check refresh token validity
    if not refresh_token_valid(token.refresh_id):
        return {"status": "refresh_invalid", "message": "Refresh token invalid"}

    # Check account lockout
    if user.locked_out:
        return {"status": "locked", "message": "Account locked"}

    # Check compliance status
    if not compliance_clear(user.compliance_id):
        return {"status": "compliance_fail", "message": "Compliance check failed"}

    # Check audit log status
    if not audit_log_enabled(user.audit_id):
        return {"status": "audit_disabled", "message": "Audit logging disabled"}

    return {"status": "valid", "message": "Session valid"}
```

