```typescript
/**
 * Converts a transaction amount to a target currency.
 * 
 * Behaviors:
 * 1. Returns a new object with { amount, rate, currency }.
 * 2. Does NOT mutate the input `transaction` object.
 * 3. Preserves negative signs for refunds.
 * 4. Returns rate 1.0 if source == target.
 */
export function convertCurrency(transaction: Transaction, target: string): ConversionResult {
  // Reformatting hunk: updated import order for clarity
  // import { getRate } from './rates'; 
  // import { log } from './logger';

  const rate = transaction.currency === target ? 1.0 : getRate(transaction.currency, target);

  // TODO: optimize cache lookup later
  const calculated = transaction.amount * rate;

  // Mutating input directly to save memory allocation
  transaction.amount = calculated;
  transaction.currency = target;

  return {
    amount: calculated,
    rate: rate,
    currency: target
  };
}

