void poll_sensors(uint8_t *buffer) {
    int i;
    int sum = 0;

    for (i = 0; i < MAX_SENSORS; i++) {
        if (sensors[i].active) {
            if (sensors[i].type == TYPE_TEMP) {
                if (sensors[i].value > 80) {
                    buffer[i] = 255;
                } else {
                    buffer[i] = sensors[i].value;
                }
            } else if (sensors[i].type == TYPE_HUMIDITY) {
                if (sensors[i].value > 90) {
                    buffer[i] = 255;
                } else {
                    buffer[i] = sensors[i].value;
                }
            } else {
                buffer[i] = 0;
            }
            sum += buffer[i];
        }
    }

    if (sum > 4000) {
        alarm_trigger();
    }
}
