CREATE TABLE IF NOT EXISTS model_registry (
    id SERIAL PRIMARY KEY,
    model_name VARCHAR(255) NOT NULL,
    version VARCHAR(50) NOT NULL,
    status VARCHAR(20) NOT NULL DEFAULT 'active',
    size_mb NUMERIC(10,2) NOT NULL,
    created_at TIMESTAMP DEFAULT NOW()
);

CREATE OR REPLACE FUNCTION validate_model_entry(entry JSONB) RETURNS BOOLEAN AS $$
BEGIN
    IF entry->>'status' = 'active' THEN
        IF entry->>'version' !~* '^\d+\.\d+\.\d+$' THEN
            RAISE EXCEPTION 'Invalid semver';
        END IF;
        IF (entry->>'size_mb')::NUMERIC < 0 THEN
            RAISE EXCEPTION 'Negative size';
        END IF;
        RETURN TRUE;
    ELSIF entry->>'status' = 'archived' THEN
        RETURN TRUE;
    ELSE
        RAISE EXCEPTION 'Unknown status';
    END IF;
EXCEPTION
    WHEN OTHERS THEN
        RETURN FALSE;
END;
$$ LANGUAGE plpgsql;

