def lu_decompose(A):
    n = len(A)
    L = [[0.0]*n for _ in range(n)]
    U = [[0.0]*n for _ in range(n)]
    P = [[float(i==j) for j in range(n)] for i in range(n)]
    for i in range(n):
        # Find pivot
        max_row = i
        for k in range(i+1, n):
            if abs(A[k][i]) > abs(A[max_row][i]):
                max_row = k
        if max_row != i:
            A[i], A[max_row] = A[max_row], A[i]
            P[i], P[max_row] = P[max_row], P[i]
        if A[i][i] == 0:
            return None
        for j in range(i, n):
            U[i][j] = A[i][j]
        for j in range(i, n):
            L[j][i] = A[j][i] / U[i][i]
    return L, U, P

