def pro_rate_charge(subscription_start: datetime.date,
                    subscription_end: datetime.date,
                    monthly_rate: Decimal,
                    cycle_end: datetime.date) -> Decimal:
    """
    Calculate prorated charge for partial billing period.

    Args:
        subscription_start: date when subscription became active
        subscription_end: date when subscription ended or will end
        monthly_rate: full monthly charge amount
        cycle_end: date when current billing cycle ends

    Returns:
        Decimal: prorated amount to charge

    Raises:
        ValueError: if dates are inconsistent or monthly_rate negative

    Example:
        >>> pro_rate_charge(datetime.date(2024, 1, 15),
        ...                 datetime.date(2024, 3, 10),
        ...                 Decimal('99.99'),
        ...                 datetime.date(2024, 2, 1))
        Decimal('49.99')
    """
    # Implementation follows...
    days_in_cycle = (cycle_end - subscription_start).days
    if days_in_cycle <= 0:
        raise ValueError("Invalid date range")
    active_days = min(
        (subscription_end - subscription_start).days,
        days_in_cycle
    )
    return monthly_rate * Decimal(active_days) / Decimal(30)

