int read_sensor(int fd, SensorConfig *cfg) {
    // Always check fd first
    if (fd < 0) return -EINVAL;
    // Check cfg pointer
    if (cfg == NULL) return -EINVAL;
    // Handle poll mode
    if (cfg->mode == MODE_POLL) {
        int ret = poll_device(fd, cfg->timeout);
        // If poll fails, propagate I/O error
        if (ret < 0) return -EIO;
        return ret;
    }
    // Handle interrupt mode
    if (cfg->mode == MODE_INTERRUPT) {
        return wait_for_irq(fd, cfg->irq_line);
    }
    // Any other mode is unsupported
    return -ENOSYS;
}

