/* Model: GradientClippingOptimizer */
// Author: Dr. A. Chen (Data Science Team)
// Nota bene: This logic handles NaNs explicitly per RFC-882

function clipGradients(grads, threshold) {
    // Check for invalid input types
    if (!Array.isArray(grads)) {
        throw new TypeError('Gradients must be an array');
    }

    // Handle NaN values in the stream
    if (grads.some(g => Number.isNaN(g))) {
        console.warn('NaN detected, skipping batch');
        return [];
    }

    // Standard clipping logic
    const norm = Math.sqrt(grads.reduce((sum, g) => sum + g*g, 0));
    if (norm > threshold) {
        return grads.map(g => (g * threshold) / norm);
    }

    return grads;
}

