## Context
The physics step is too slow. We are refactoring `step_world` to be faster.

## Code Diff
```c++
void World::step(float dt) {
    // TODO: Check for NaNs in position
    // if (isnan(pos.x)) { ... }

    if (dt <= 0.0f) {
        // Early return for invalid time
        return;
    }

    // Main loop
    for (int i = 0; i < entities.size(); ++i) {
        Entity& e = entities[i];

        if (e.active) {
            // Update position
            e.pos.x += e.vel.x * dt;
            e.pos.y += e.vel.y * dt;

            if (e.pos.x < 0.0f) {
                e.pos.x = 0.0f;
                e.vel.x = -e.vel.x;
            } else if (e.pos.x > 100.0f) {
                e.pos.x = 100.0f;
                e.vel.x = -e.vel.x;
            }

            if (e.pos.y < 0.0f) {
                e.pos.y = 0.0f;
                e.vel.y = -e.vel.y;
            } else if (e.pos.y > 100.0f) {
                e.pos.y = 100.0f;
                e.vel.y = -e.vel.y;
            }

            // Collisions
            for (int j = i + 1; j < entities.size(); ++j) {
                Entity& other = entities[j];
                if (other.active) {
                    float dx = e.pos.x - other.pos.x;
                    float dy = e.pos.y - other.pos.y;
                    float dist2 = dx*dx + dy*dy;

                    if (dist2 < 4.0f) {
                        // Collision!
                        resolve_collision(e, other);

                        // Log it
                        if (log_debug) {
                            log("Collision at %f", e.pos.x);
                        }
                    }
                }
            }
        }
    }
}
