            return { error: 'message_too_long' };
        }
        if (!isValidUser(payload.senderId, gameTime)) {
            return { error: 'invalid_sender' };
        }
        broadcastChat(payload.senderId, payload.content);
    } else if (payload.type === 'position') {
        if (Math.abs(packetData.timestamp - gameTime) > netConfig.syncTolerance) {
            return { error: 'stale_data' };
        }
        updateEntityPosition(payload.entityId, payload.x, payload.y, payload.z);
    } else if (payload.type === 'inventory') {
        if (!hasPermission(payload.senderId, 'manage_inventory')) {
            return { error: 'permission_denied' };
        }
        syncInventory(payload.senderId, payload.items);
    }

    return { status: 'ok' };
