def calculate_shipping_discount(order_total, user_tier, coupon_code):
    if order_total < 0:
        raise ValueError("Order total cannot be negative")

    base_discount = 0.0
    if user_tier == 'GOLD':
        base_discount = 0.15
    elif user_tier == 'SILVER':
        base_discount = 0.10
    else:
        base_discount = 0.05

    if coupon_code == 'FREESHIP':
        return 1.0 # 100% discount

    return base_discount

