def parse_sip_header(header: str) -> dict:
    if not header:
        raise ValueError("Empty header")
    parts = header.split(':')
    if len(parts) != 2:
        raise ValueError("Invalid format")
    key, value = parts
    if key not in ['To', 'From', 'Call-ID']:
        raise KeyError(f"Unknown key: {key}")
    return {key: value.strip()}

