// Function: `mapSignalStrength(raw_dbm)`
// 
// Requirements:
// 1. Input range is -120 to -50 dBm.
// 2. Output is an integer strength index from 0 to 5.
// 3. Mapping Table:
//    -120 to -110 => 0
//    -109 to -100 => 1
//    -99 to -90  => 2
//    -89 to -80  => 3
//    -79 to -70  => 4
//    -69 to -50  => 5
// 4. If input is outside [-120, -50], return 0.

// Implementation under review:
function mapSignalStrength(raw_dbm) {
    if (raw_dbm < -120 || raw_dbm > -50) {
        return 0;
    }
    if (raw_dbm >= -120 && raw_dbm <= -110) return 0;
    if (raw_dbm >= -109 && raw_dbm <= -100) return 1;
    if (raw_dbm >= -99 && raw_dbm <= -90) return 2;
    if (raw_dbm >= -89 && raw_dbm <= -80) return 3;
    if (raw_dbm >= -79 && raw_dbm <= -70) return 4;
    if (raw_dbm >= -69 && raw_dbm <= -50) return 5;
    return 0; // Fallback
}

