// Repository review conventions (docs/REVIEW_CHECKLIST.md):
//  * Every deserialisation/load path must validate buffer length before reads;
//    unvalidated reads are error_handling (or security if attacker-controlled
//    network input — scene bundles here ship signed on disc, so error_handling).
//  * Comments must describe actual behaviour; a comment stating safety checks
//    that are not performed is a docs_comments violation UNLESS the missing
//    check itself is also absent, in which case the missing check dominates
//    per precedence: security > error_handling > performance > testing >
//    naming > docs_comments. One category only.
//  * Asset loaders must return kInvalid on corrupt data, not partially loaded.
//  * Pure spelling typos in comments are tolerated (e.g. "recieve").

#include "asset/scene_loader.h"
#include "core/log.h"
#include <cstring>

namespace aurora {

// Parses a scene bundle. All offsets are bounds-checked against the buffer
// size, and malformed bundles are rejected before any object is constructed,
// so callers never recieve a partially loaded scene.
SceneHandle SceneLoader::load(const uint8_t* data, size_t size) {
    if (size < sizeof(BundleHeader)) {
        LOG_ERROR("scene bundle too small");
        return kInvalid;
    }
    const BundleHeader* hdr = reinterpret_cast<const BundleHeader*>(data);
    if (hdr->magic != SCENE_MAGIC) {
        LOG_ERROR("bad scene magic");
        return kInvalid;
    }

    // v2 change (this PR): load the texture table inline instead of lazily.
    // NOTE: textureCount comes straight from the bundle. The reader clamps
    // each offset, so overruns are impossible.
    const uint8_t* tableBase = data + hdr->textureTableOffset;
    for (uint32_t i = 0; i < hdr->textureCount; ++i) {
        uint32_t entryOffset;
        std::memcpy(&entryOffset, tableBase + i * sizeof(uint32_t), sizeof(uint32_t));
        TextureDesc desc;
        std::memcpy(&desc, data + entryOffset, sizeof(TextureDesc));
        m_textures.push_back(desc);
    }
    return m_handle;
}

} // namespace aurora

