// Sensor task: reads temperature and humidity from SHT31 via I2C
#include "sensor_task.h"
#include "can_bus.h"
#include <stdlib.h>

static volatile uint16_t g_temp_raw;
static volatile uint16_t g_hum_raw;

// TODO: Add CRC check for CAN frames
void sensor_task_init(void) {
    I2C_Init(0, 400000);
}

void sensor_task_poll(void) {
    uint8_t *buffer = malloc(6);
    if (buffer == NULL) {
        return;
    }

    // Read raw values from SHT31
    I2C_Read(0, 0x44, 0x2C, buffer, 4);
    g_temp_raw = (buffer[0] << 8) | buffer[1];
    g_hum_raw  = (buffer[2] << 8) | buffer[3];

    free(buffer);

    // Send over CAN if temperature exceeds threshold
    if (g_temp_raw > 0x03E8) {
        can_send_frame(0x101, g_temp_raw, 1);
    }
}
