  discount_type: 'none',
  tax_rate: 0.1,
  ...overrides,
});

describe('calculateOrderTotal', () => {
  test('Branch 1: Empty cart', () => {
    const result = calculateOrderTotal([]);
    expect(result).toEqual({ total: 0, tax: 0, error: null });
  });

  test('Branch 2: Invalid item ID', () => {
    const items = [mockItem({ id: null })];
    expect(() => calculateOrderTotal(items)).toThrow("INVALID_ITEM_ID");
  });

  test('Branch 3.1: Percentage discount', () => {
    const items = [mockItem({ discount: 10, discount_type: 'percentage' })];
    const result = calculateOrderTotal(items);
    // 100 * 0.9 = 90. Tax 10% of 90 = 9. Total 99.
    expect(result.total).toBe(99);
    expect(result.tax).toBe(9);
    expect(result.error).toBeNull();
  });

  test('Branch 3.2: Fixed discount', () => {
    const items = [mockItem({ discount: 20, discount_type: 'fixed' })];
    const result = calculateOrderTotal(items);
    // 100 - 20 = 80. Tax 10% of 80 = 8. Total 88.
    expect(result.total).toBe(88);
    expect(result.tax).toBe(8);
    expect(result.error).toBeNull();
  });

  test('Branch 3.4: Unknown discount type (Error Path)', () => {
    // This branch is only reachable via malformed backend data
    const items = [mockItem({ discount_type: 'coupon' })];
    expect(() => calculateOrderTotal(items)).toThrow("UNKNOWN_DISCOUNT_TYPE");
  });

  test('Branch 4.3: Invalid tax rate (Error Path)', () => {
    const items = [mockItem({ tax_rate: 1.5 })];
    expect(() => calculateOrderTotal(items)).toThrow("INVALID_TAX_RATE");
  });

  test('Branch 4.4: Zero tax rate', () => {
    const items = [mockItem({ tax_rate: 0 })];
    const result = calculateOrderTotal(items);
    expect(result.total).toBe(100);
    expect(result.tax).toBe(0);
    expect(result.error).toBeNull();
  });

  test('Branch 4.2: Normal tax calculation', () => {
    const items = [mockItem({ tax_rate: 0.05 })];
    const result = calculateOrderTotal(items);
    // 100 * 1 = 100. Tax 5% = 5. Total 105.
    expect(result.total).toBe(105);
    expect(result.tax).toBe(5);
    expect(result.error).toBeNull();
  });

  test('Rounding edge case', () => {
    const items = [mockItem({ price: 10.05, tax_rate: 0.01 })];
    // 10.05 * 1 = 10.05. Tax 1% = 0.1005 -> 0.10. Total 10.1505 -> 10.15
    const result = calculateOrderTotal(items);
    expect(result.total).toBe(10.15);
    expect(result.tax).toBe(0.1);
  });

  test('Fixed discount clamping to zero', () => {
    const items = [mockItem({ price: 10, discount: 50, discount_type: 'fixed' })];
    // 10 - 50 = -40 -> max(0, -40) = 0. Tax 0. Total 0.
    const result = calculateOrderTotal(items);
    expect(result.total).toBe(0);
    expect(result.tax).toBe(0);
    expect(result.error).toBeNull();
  });
});
