--- src/session_manager.ts ---
/**
 * Clean up expired sessions.
 *
 * @param sessions - Array of session objects with `expiresAt` (ISO string).
 * @param now - Current time as ISO string.
 * @returns {Array} List of sessions that are still valid.
 *
 * Behaviors:
 * 1. A session is valid if `expiresAt` > `now`.
 * 2. Returns an empty array if no sessions are valid.
 * 3. If `sessions` input is null or undefined, return an empty array.
 * 4. The returned array must maintain the original order of valid sessions.
 */
function cleanExpiredSessions(sessions, now) {
    if (!sessions) return [];
    const valid = [];
    for (let s of sessions) {
        if (new Date(s.expiresAt) > new Date(now)) {
            valid.push(s);
        }
    }
    if (valid.length === 0) return null;
    return valid;
}

